// Step 1: Normalize & Extract Receipt Data
const body = $input.first().json.body || $input.first().json;
const rawReceipt = body.receipt || body.text || '';
const orderId = body.orderId || '';
const expectedAmount = Number(body.expectedAmount || 0);

// 12-digit UTR Regex
const utrMatch = rawReceipt.match(/\b\d{12}\b/);
const utr = utrMatch ? utrMatch[0] : null;

// Amount Regex
const amountMatch = rawReceipt.match(/(?:(?:₹|Rs\.?|INR)\s*|paid\s+|amount\s*:?\s*)([0-9]+(?:\.[0-9]{1,2})?)/i) ||
                    rawReceipt.match(/\b([0-9]+\.[0-9]{2})\b/);
const parsedAmount = amountMatch ? parseFloat(amountMatch[1]) : null;

// Note Regex
const noteMatch = rawReceipt.match(/\b(Order_[A-Za-z0-9_-]+)\b/i);
const parsedNote = noteMatch ? noteMatch[1] : null;

return [{
  json: {
    rawReceipt,
    orderId,
    expectedAmount,
    utr,
    parsedAmount,
    parsedNote,
    sessionToken: body.sessionToken || null,
    receivedAt: new Date().toISOString()
  }
}];

// Step 2: NPCI UTR Forensic Freshness & Mathematical Validation
const data = $input.first().json;
const utr = data.utr;

if (!utr || data.parsedAmount === null) {
  return [{ json: { ...data, isValid: false, reason: 'PARSE_ERROR' } }];
}

// IST Date calculation
const now = new Date();
const istOffset = 5.5 * 60 * 60 * 1000;
const istNow = new Date(now.getTime() + istOffset);
const curYearDigit = istNow.getUTCFullYear() % 10;
const startOfYear = new Date(Date.UTC(istNow.getUTCFullYear(), 0, 1));
const curJulianDay = Math.floor((istNow - startOfYear) / (24 * 60 * 60 * 1000)) + 1;
const curHour = istNow.getUTCHours();

const utrYear = parseInt(utr[0], 10);
const utrJulian = parseInt(utr.substring(1, 4), 10);
const utrHour = parseInt(utr.substring(4, 6), 10);

// Check 1: Year match
if (utrYear !== curYearDigit) {
  return [{ json: { ...data, isValid: false, reason: 'STALE_UTR_YEAR_MISMATCH' } }];
}

// Check 2: Julian day match
const isToday = utrJulian === curJulianDay;
const isYesterday = (curJulianDay - utrJulian === 1) || (curJulianDay === 1 && utrJulian >= 365);
if (!isToday && !isYesterday) {
  return [{ json: { ...data, isValid: false, reason: 'STALE_UTR_DATE_MISMATCH' } }];
}

// Check 3: Hour window
const hourDiff = isToday ? (curHour - utrHour) : ((curHour + 24) - utrHour);
if (hourDiff < 0 || hourDiff > 1) {
  return [{ json: { ...data, isValid: false, reason: 'STALE_UTR_HOURLY_WINDOW_EXPIRED' } }];
}

// Check 4: Amount match
if (data.expectedAmount > 0 && Math.abs(data.parsedAmount - data.expectedAmount) > 0.009) {
  return [{ json: { ...data, isValid: false, reason: 'AMOUNT_MISMATCH' } }];
}

// Check 5: Transaction Note match
if (data.parsedNote && data.orderId && data.parsedNote !== data.orderId) {
  return [{ json: { ...data, isValid: false, reason: 'NOTE_MISMATCH' } }];
}

return [{
  json: {
    ...data,
    isValid: true,
    reason: 'VERIFIED_FRESH'
  }
}];

